export function addBusinessDays(start: Date, n: number): Date {
  const result = new Date(start.getTime());
  if (n === 0) {
    return result;
  }
  let counted = 0;
  while (counted < n) {
    result.setUTCDate(result.getUTCDate() + 1);
    const day = result.getUTCDay();
    if (day !== 0 && day !== 6) {
      counted += 1;
    }
  }
  return result;
}

