export function addBusinessDays(start: Date, n: number): Date {
  const result = new Date(start.getTime());
  if (n === 0) {
    return result;
  }
  const weeks = Math.floor(n / 5);
  const remainder = n % 5;
  const calendarDays = weeks * 7 + remainder;
  result.setUTCDate(result.getUTCDate() + calendarDays);
  return result;
}

