const assert = require("assert");
const { addBusinessDays } = require("./build/dates.js");

function iso(d) {
  return d.toISOString().slice(0, 10);
}

{
  const d = new Date(Date.UTC(2024, 5, 1)); // Saturday
  assert.strictEqual(iso(addBusinessDays(d, 0)), iso(d));
}
{
  const friday = new Date(Date.UTC(2024, 4, 31));
  assert.strictEqual(iso(addBusinessDays(friday, 1)), "2024-06-03");
}
{
  const monday = new Date(Date.UTC(2024, 4, 27));
  assert.strictEqual(iso(addBusinessDays(monday, 5)), "2024-06-03");
}
{
  const friday = new Date(Date.UTC(2024, 11, 27));
  assert.strictEqual(iso(addBusinessDays(friday, 3)), "2025-01-01");
}
{
  const saturday = new Date(Date.UTC(2024, 5, 1));
  assert.strictEqual(iso(addBusinessDays(saturday, 1)), "2024-06-03");
}
console.log("behavior OK");
